// Copies Excalidraw's fonts from node_modules into public/excalidraw/fonts/,
// so the canvas (src/ui/CanvasExcalidraw.tsx) loads them SAME-ORIGIN through
// `EXCALIDRAW_ASSET_PATH` — the app's CSP allows no CDN, and under the
// local-only policy nothing may leave the device — and works offline.
// public/excalidraw/ is git-ignored and regenerated by predev/prebuild.
// The fonts: Excalifont, Virgil, Cascadia, Comic Shanns, Liberation Sans,
// Lilita One, Nunito, Assistant (Hebrew) and Xiaolai (CJK, 13 MB, fetched
// only when CJK text is drawn).
import { copyFileSync, existsSync, mkdirSync, readdirSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, "..", "node_modules", "@excalidraw", "excalidraw", "dist", "prod", "fonts");
const outDir = join(here, "..", "public", "excalidraw", "fonts");

if (!existsSync(src)) {
  console.warn("copy-excalidraw: @excalidraw/excalidraw not installed — the canvas fonts will be unavailable");
  process.exit(0);
}
let files = 0;
let total = 0;
const walk = (from, to) => {
  mkdirSync(to, { recursive: true });
  for (const name of readdirSync(from)) {
    const s = join(from, name);
    const d = join(to, name);
    if (statSync(s).isDirectory()) {
      walk(s, d);
      continue;
    }
    if (!existsSync(d) || statSync(d).size !== statSync(s).size) copyFileSync(s, d);
    files++;
    total += statSync(s).size;
  }
};
walk(src, outDir);
console.log(`copy-excalidraw: ${files} font files → public/excalidraw/fonts/ (${(total / 1e6).toFixed(1)} MB)`);
